INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 1, 'Editor''s Note: Named Bourbon Chicken because it was supposedly created by a Chinese cook who worked in a restaurant on Bourbon Street.' FROM recipes WHERE external_source_id = '45809' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 2, 'Heat oil in a large skillet.' FROM recipes WHERE external_source_id = '45809' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 3, 'Add chicken pieces and cook until lightly browned.' FROM recipes WHERE external_source_id = '45809' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 4, 'Remove chicken.' FROM recipes WHERE external_source_id = '45809' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 5, 'Add remaining ingredients, heating over medium Heat until well mixed and dissolved.' FROM recipes WHERE external_source_id = '45809' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 6, 'Add chicken and bring to a hard boil.' FROM recipes WHERE external_source_id = '45809' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 7, 'Reduce heat and simmer for 20 minutes.' FROM recipes WHERE external_source_id = '45809' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 8, 'Serve over hot rice and ENJOY.' FROM recipes WHERE external_source_id = '45809' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 1, 'Remove odd pots and pans from oven.' FROM recipes WHERE external_source_id = '2886' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 2, 'Preheat oven to 350º / 180º.' FROM recipes WHERE external_source_id = '2886' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 3, 'Cream together butter and sugar.' FROM recipes WHERE external_source_id = '2886' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 4, 'Add eggs and crushed bananas.' FROM recipes WHERE external_source_id = '2886' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 5, 'Combine well.' FROM recipes WHERE external_source_id = '2886' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 6, 'Sift together flour, soda and salt. Add to creamed mixture. Add vanilla.' FROM recipes WHERE external_source_id = '2886' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 7, 'Mix just until combined. Do not overmix.' FROM recipes WHERE external_source_id = '2886' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 8, 'Pour into greased and floured loaf pan.' FROM recipes WHERE external_source_id = '2886' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 9, 'Bake at 350º / 180º for 55 minutes.' FROM recipes WHERE external_source_id = '2886' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 10, 'Keeps well, refrigerated.' FROM recipes WHERE external_source_id = '2886' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 1, 'Place beef roast in crock pot.' FROM recipes WHERE external_source_id = '27208' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 2, 'Mix the dried mixes together in a bowl and sprinkle over the roast.' FROM recipes WHERE external_source_id = '27208' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 3, 'Pour the water around the roast.' FROM recipes WHERE external_source_id = '27208' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 4, 'Cook on low for 7-9 hours.' FROM recipes WHERE external_source_id = '27208' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 5, 'Optional tweaks:' FROM recipes WHERE external_source_id = '27208' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 6, '1. Use onion soup mix instead of ranch.' FROM recipes WHERE external_source_id = '27208' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 7, '2. Add one cup of red wine along with the water.' FROM recipes WHERE external_source_id = '27208' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 8, '3. Add potatoes, carrots, mushrooms, celery and onion 2-3 hours before end.' FROM recipes WHERE external_source_id = '27208' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 1, 'Take 4-5 frozen, yes, frozen, boneless chicken breasts put into crock pot.' FROM recipes WHERE external_source_id = '89204' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 2, 'Add 1 can of black beans, drained, 1 jar of salsa, 1 can of corn drained.' FROM recipes WHERE external_source_id = '89204' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 3, 'Keep in crock pot on high for about 4-5 hours or until chicken is cooked.' FROM recipes WHERE external_source_id = '89204' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 4, 'Add 1 package of cream cheese (just throw it on top!) and let sit for about 1/2 hour.' FROM recipes WHERE external_source_id = '89204' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 5, 'All done and enjoy!' FROM recipes WHERE external_source_id = '89204' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 1, 'Place chicken and Cajun seasoning in a bowl and toss to coat.' FROM recipes WHERE external_source_id = '39087' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 2, 'In a large skillet over medium heat, sauté chicken in butter or margarine until chicken is tender, about 5 to 7 minutes.' FROM recipes WHERE external_source_id = '39087' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 3, 'Reduce heat add green onion, heavy cream, tomatoes, basil, salt, garlic powder, black pepper and heat through.' FROM recipes WHERE external_source_id = '39087' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 4, 'Pour over hot linguine and toss with Parmesan cheese.' FROM recipes WHERE external_source_id = '39087' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 1, 'Meatloaf: Combine meat loaf ingredients and place into a loaf baking dish.' FROM recipes WHERE external_source_id = '54257' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 2, 'Smooth out top.' FROM recipes WHERE external_source_id = '54257' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 3, 'Sauce: Combine sauce ingredients and pour on top and sides of meatloaf.' FROM recipes WHERE external_source_id = '54257' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 4, 'Bake at 350°F about 1 hour to 1 hour 15 minutes or until done.' FROM recipes WHERE external_source_id = '54257' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 5, 'ENJOY!' FROM recipes WHERE external_source_id = '54257' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 6, '*The addition of 1 or 2 teaspoons of Kitchen Bouquet® makes this recipe very good.' FROM recipes WHERE external_source_id = '54257' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 7, '**Recipe should be"plump" from the addition of the milk or Half & Half.' FROM recipes WHERE external_source_id = '54257' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 8, 'It should NOT be runny.' FROM recipes WHERE external_source_id = '54257' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 9, '***A second batch of sauce served hot is good to serve with the meatloaf.' FROM recipes WHERE external_source_id = '54257' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 10, 'Nita''s Note: I note that some of you are using game meat such as deer -- Deer is a very DRY meat. It is wise to HAVE some fat added to the deer -- especially to ground deer. Maybe 25 % fat, ( I recommend 1 lb of ground venison, and 1/2 lb of deer sausage for fat content), otherwise your results will be poor. I don''t know about some of the other game meat some are using. Please consult an expert. The recipe is delicious as it stands! Enjoy! Nita Holleman.' FROM recipes WHERE external_source_id = '54257' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 1, 'In large, heavy stockpot, brown Italian sausage, breaking up as you stir.' FROM recipes WHERE external_source_id = '22782' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 2, 'Add onions and continue to cook, stirring occasionally until onions are softened.' FROM recipes WHERE external_source_id = '22782' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 3, 'Add garlic, tomatoes, tomato paste, tomato sauce and water.' FROM recipes WHERE external_source_id = '22782' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 4, 'Add basil, parsley, brown sugar, salt, crushed red pepper, and black pepper.' FROM recipes WHERE external_source_id = '22782' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 5, 'Stir well and barely bring to a boil.' FROM recipes WHERE external_source_id = '22782' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 6, 'Stir in red wine.' FROM recipes WHERE external_source_id = '22782' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 7, 'Simmer on low, stirring frequently for at least an hour. A longer simmer makes for a better sauce, just be careful not to let it burn!' FROM recipes WHERE external_source_id = '22782' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 8, 'Cook spaghetti according to package directions.' FROM recipes WHERE external_source_id = '22782' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 9, 'Spoon sauce over drained spaghetti noodles and sprinkle with parmesan cheese.' FROM recipes WHERE external_source_id = '22782' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 1, 'Beat egg until fluffy.' FROM recipes WHERE external_source_id = '25690' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 2, 'Add milk and melted margarine.' FROM recipes WHERE external_source_id = '25690' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 3, 'Add dry ingredients and mix well.' FROM recipes WHERE external_source_id = '25690' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 4, 'Heat a heavy griddle or fry pan which is greased with a little butter on a paper towel.' FROM recipes WHERE external_source_id = '25690' ON CONFLICT (recipe_id, step_number) DO NOTHING;
