INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 4, 'Place rice in a fine mesh strainer and rinse under cold running water until water runs clear- about 1 1/2 minutes.Shake rice vigorously to remove excess water.This step removes the starch from the rice so it will not stick. IF YOU OMIT THIS STEP YOUR RICE WILL NOT BE DRY AND FLUFFY.' FROM recipes WHERE external_source_id = '117892' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 5, 'Heat oil in heavy bottomed ovensafe 12 inch straight sided sautee pan or Dutch oven with tight fitting lid over low-medium heat about 2 minutes. (The recipe is very specific about this but I used a 10 inch dutch oven and it worked out fine.) Drop a few rice grains in and if they sizzle then it is ready. Add rice and fry stirring until rice is light golden and translucent, about 6-8 minutes. Be careful that the oil doesn''t get too hot too fast or the oil will splatter.' FROM recipes WHERE external_source_id = '117892' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 6, 'Reduce heat to medium, add garlic and 2 minced jalapenos and cook , stirring constantly until fragrant, about 1 1/2 minutes.' FROM recipes WHERE external_source_id = '117892' ON CONFLICT (recipe_id, step_number) DO NOTHING;
